  double get _protein=>_items.fold(0.0,(s,item)=>s+(item['analysis'] as MealItemAnalysis).protein);
  double get _carbs=>_items.fold(0.0,(s,item)=>s+(item['analysis'] as MealItemAnalysis).carbs);
  double get _fat=>_items.fold(0.0,(s,item)=>s+(item['analysis'] as MealItemAnalysis).fat);
  double get _fiber=>_items.fold(0.0,(s,item)=>s+(item['analysis'] as MealItemAnalysis).fiber);
  @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Ajustar Porções')),body:SafeArea(child:Column(children:[Expanded(child:ListView.builder(padding:const EdgeInsets.all(20),itemCount:_items.length,itemBuilder:(context,index){final item=_items[index];final a=item['analysis'] as MealItemAnalysis;final unit=item['unit'] as String;final step=portionStep(unit);return Card(margin:const EdgeInsets.only(bottom:12),child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(a.foodName,style:const TextStyle(fontWeight:FontWeight.bold,fontSize:16)),const SizedBox(height:2),Text('${a.calories.toStringAsFixed(0)} kcal • ${a.protein.toStringAsFixed(1)} g proteína',style:Theme.of(context).textTheme.bodySmall)])),IconButton(tooltip:'Editar alimento',icon:const Icon(Icons.edit_outlined),onPressed:()=>_editFood(index)),IconButton(tooltip:'Remover alimento',icon:const Icon(Icons.remove_circle_outline,color:Colors.red),onPressed:()=>_remove(index))]),const SizedBox(height:12),Row(children:[SizedBox(width:76,child:TextField(controller:_controllers[index],keyboardType:const TextInputType.numberWithOptions(decimal:true),textAlign:TextAlign.center,decoration:const InputDecoration(labelText:'Qtd.',border:OutlineInputBorder(),isDense:true),onChanged:(v){final p=double.tryParse(v.replaceAll(',','.'));if(p!=null&&p>0){_items[index]['quantity']=p;final old=_items[index]['analysis'] as MealItemAnalysis;_items[index]['analysis']=analyzeFoodItem(old.foodName,p,unit);setState((){});}})),const SizedBox(width:4),Container(height:48,width:36,decoration:BoxDecoration(border:Border.all(color:Theme.of(context).dividerColor),borderRadius:BorderRadius.circular(8)),child:Column(children:[Expanded(child:IconButton(padding:EdgeInsets.zero,tooltip:'Aumentar',icon:const Icon(Icons.keyboard_arrow_up,size:20),onPressed:()=>_changeQuantity(index,step))),Expanded(child:IconButton(padding:EdgeInsets.zero,tooltip:'Diminuir',icon:const Icon(Icons.keyboard_arrow_down,size:20),onPressed:()=>_changeQuantity(index,-step)))])),const SizedBox(width:8),Expanded(child:DropdownButtonFormField<String>(initialValue:unit,isExpanded:true,decoration:const InputDecoration(labelText:'Unidade',border:OutlineInputBorder(),isDense:true),items:a.unitWeights.keys.map((u)=>DropdownMenuItem(value:u,child:Text(u,overflow:TextOverflow.ellipsis))).toList(),onChanged:(v){if(v!=null)_changeUnit(index,v);}))]),const SizedBox(height:10),Wrap(spacing:10,runSpacing:4,children:[Text('${a.carbs.toStringAsFixed(1)} g carboidratos',style:Theme.of(context).textTheme.bodySmall),Text('${a.fat.toStringAsFixed(1)} g gorduras',style:Theme.of(context).textTheme.bodySmall),Text('${a.fiber.toStringAsFixed(1)} g fibras',style:Theme.of(context).textTheme.bodySmall)])])));}),),Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(color:Theme.of(context).colorScheme.surfaceContainerHighest.withValues(alpha:.3),borderRadius:const BorderRadius.vertical(top:Radius.circular(24))),child:Column(children:[Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[const Text('Total Estimado:',style:TextStyle(fontSize:16,fontWeight:FontWeight.w600)),Text('${_totalCalories.toStringAsFixed(0)} kcal',style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w900,color:NutriTheme.green))]),const SizedBox(height:10),Wrap(alignment:WrapAlignment.center,spacing:14,runSpacing:4,children:[Text('P ${_protein.toStringAsFixed(1)}g'),Text('C ${_carbs.toStringAsFixed(1)}g'),Text('G ${_fat.toStringAsFixed(1)}g'),Text('F ${_fiber.toStringAsFixed(1)}g')]),const SizedBox(height:16),SizedBox(width:double.infinity,child:FilledButton(onPressed:_items.isEmpty?null:(){final finalItems=_items.map((e)=>e['analysis'] as MealItemAnalysis).toList();Navigator.push(context,MaterialPageRoute(builder:(_)=>MealAnalysisPage(mealName:widget.mealName,mealType:widget.mealType,items:finalItems,calories:_totalCalories)));},child:const Text('Ver Análise Final')))]))])));
}
